"shell","arguments":{"command":"python3 << 'EOF'\nimport json\n\n# Data from Table 2 - Computed annual interest charge on Public debt (in millions)\ndata = {\n    1961: 3072,\n    1962: 3239,\n    1963: 3360,\n    1964: 3560,\n    1965: 3678,\n    1966: 3988,\n    1967: 4039,\n    1968: 4499\n}\n\n# Convert to billions\nyears = list(data.keys())\nvalues = [data[y] / 1000 for y in years]  # Convert to billions\n\nprint(\"FY 1961-1967 data (in billions):\")\nfor y in years[:-1]:\n    print(f\"FY {y}: {data[y]/1000:.3f} billion\")\n\nprint(f\"\\nFY 1968 actual: {data[2013]/1000 if 2013 in data else 'N/A'} billion\")\n\n# Now do OLS regression for FY 1961-1967\nimport numpy as np\n\n# X = fiscal year (using 1961=1, 1962=2, etc for simplicity)\nX = np.array([y - 1960 for y in years[:-1]])  # 1961 -> 1, 1962 -> 2, ..., 1967 -> 7\ny = np.array(values[:-1])  # 1961-1967\n\n# OLS: y = beta0 + beta1 * X\nn = len(X)\nsum_x = np.sum(X)\nsum_y = np.sum(y)\nsum_xy = np.sum(X * y)\nsum_x2 = np.sum(X ** 2)\n\nbeta1 = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x ** 2)\nbeta0 = (sum_y - beta1 * sum_x) / n\n\nprint(f\"\\nOLS Regression: y = {beta0:.6f} + {beta1:.6f} * X\")\nprint(f\"where X = FY year - 1960\")\n\n# Forecast FY 1968 (X = 8, since 1968 - 1960 = 8)\nX_1968 = 8\nforecast_1968 = beta0 + beta1 * X_1968\n\nprint(f\"\\nFY 1968 Forecast: {forecast_1968:.6f} billion dollars\")\nprint(f\"FY 1968 Actual: {values[-1]:.6f} billion dollars\")\n\n# Forecast error = actual - forecast\nforecast_error = values[-1] - forecast_1968\nprint(f\"\\nForecast Error (actual - forecast): {forecast_error:.6f} billion dollars\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
